import { CloudUpload, PackageCheck, QrCode, Route, ScanLine, type LucideIcon } from "lucide-react";
import { useEffect, useRef, useState } from "react";
import { useReducedMotion } from "../lib/preferences";
import { Container } from "./shared";

/*
 * "Behind the link": what happens between a scan and someone opening the map, in
 * five stops on one coral route. Laptop: a row, the route runs left to right. Phone:
 * a column, the route runs down the left. When the section scrolls into view the
 * route draws itself and the stops appear one after another; the dashes then keep
 * flowing toward the last stop. With Reduce motion everything is already there.
 *
 * Each line matches what the code does today:
 *   Scan     apps/capture (Path Capture records triangles, colored points, photos; works offline)
 *   Upload   services/api POST /api/scans (GLB from the website) or /api/captures (app bundle)
 *   Prepare  CPU processor checks checksums and makes the phone-sized scene.glb;
 *            Gemini drafts landmark cues the owner approves
 *   Share    Public / Unlisted / Private, link or QR
 *   Open     the browser builds the walkable floor (lib/navmesh.ts) and routes on it
 */

interface Stop {
  icon: LucideIcon;
  title: string;
  line: string;
}

const STOPS: Stop[] = [
  { icon: ScanLine, title: "Scan", line: "Walk the place with a LiDAR iPhone. It records the 3D shape and photos." },
  { icon: CloudUpload, title: "Upload", line: "Send it from the Path Capture app, or drop a 3D file on the website." },
  { icon: PackageCheck, title: "Prepare", line: "The server checks it, makes a light copy for phones and drafts landmark tips." },
  { icon: QrCode, title: "Share", line: "Pick Public, Unlisted or Private, then send the link or QR code." },
  { icon: Route, title: "Open anywhere", line: "Any browser shows the 3D map and finds a walking route. No app needed." },
];

/** Seconds between one stop appearing and the next. */
const STAGGER = 0.28;

export default function Pipeline() {
  const reduce = useReducedMotion();
  const list = useRef<HTMLOListElement>(null);
  const [shown, setShown] = useState(false);

  useEffect(() => {
    const el = list.current;
    if (!el || shown) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry?.isIntersecting) setShown(true);
      },
      { threshold: 0.35 },
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, [shown]);

  const on = shown || reduce;

  return (
    <section id="pipeline" aria-labelledby="pipeline-heading" className="bg-paper py-24 md:py-32">
      <Container>
        <div className="mx-auto grid max-w-2xl gap-3 text-center">
          <p className="font-mono text-sm font-bold tracking-wide text-rust uppercase">Behind the link</p>
          <h2 id="pipeline-heading" className="font-display text-[clamp(2rem,3.6vw,3rem)] leading-none font-black text-balance">
            From one scan to a map anyone can open.
          </h2>
        </div>

        <ol ref={list} className="relative mx-auto mt-14 grid max-w-md gap-9 lg:mt-20 lg:max-w-none lg:grid-cols-5 lg:gap-6 xl-text:lg:max-w-md xl-text:lg:grid-cols-1">
          {/* The route: down the left on phones, across the icons on laptops. */}
          <div
            aria-hidden="true"
            className={`pipe-route-y absolute top-8 bottom-8 left-[calc(2rem-2px)] w-1 transition-[clip-path] duration-[1600ms] ease-out lg:hidden xl-text:lg:block ${
              on ? "[clip-path:inset(0)]" : "[clip-path:inset(0_0_100%_0)]"
            }`}
          />
          <div
            aria-hidden="true"
            className={`pipe-route-x absolute top-[calc(2rem-2px)] right-[10%] left-[10%] hidden h-1 transition-[clip-path] duration-[1600ms] ease-out lg:block xl-text:lg:hidden ${
              on ? "[clip-path:inset(0)]" : "[clip-path:inset(0_100%_0_0)]"
            }`}
          />

          {STOPS.map((stop, i) => {
            const Icon = stop.icon;
            const last = i === STOPS.length - 1;
            return (
              <li
                key={stop.title}
                className={`relative grid grid-cols-[4rem_minmax(0,1fr)] items-start gap-x-5 transition-[opacity,translate] duration-500 ease-out lg:grid-cols-1 lg:justify-items-center lg:gap-y-5 lg:text-center xl-text:lg:grid-cols-[4rem_minmax(0,1fr)] xl-text:lg:justify-items-stretch xl-text:lg:text-left ${
                  on ? "translate-y-0 opacity-100" : "translate-y-3 opacity-0"
                }`}
                style={{ transitionDelay: on && !reduce ? `${0.2 + i * STAGGER}s` : "0s" }}
              >
                <span
                  aria-hidden="true"
                  className={`grid size-16 place-items-center rounded-full ring-8 ring-paper ${last ? "bg-coral text-ink" : "bg-night text-sage"}`}
                >
                  <Icon className="size-7" strokeWidth={2} />
                </span>
                <div className="pt-1 lg:pt-0 xl-text:lg:pt-1">
                  <p className="font-mono text-sm text-muted">0{i + 1}</p>
                  <h3 className="font-display text-2xl leading-tight font-black">{stop.title}</h3>
                  <p className="mt-1.5 text-lg leading-snug text-balance text-muted">{stop.line}</p>
                </div>
              </li>
            );
          })}
        </ol>
      </Container>
    </section>
  );
}

